#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int n, a[3];
    if (scanf("%d %d %d %d", &n, &a[0], &a[1], &a[2]) != 4) {
        return 0;
    }

    // Ordenação simples de 3 elementos
    if (a[0] > a[1]) swap(&a[0], &a[1]);
    if (a[1] > a[2]) swap(&a[1], &a[2]);
    if (a[0] > a[1]) swap(&a[0], &a[1]);

    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (n >= a[i]) {
            n -= a[i];
            count++;
        } else {
            break;
        }
    }

    printf("%d\n", count);

    return 0;
}
